/* Presentation and suggested study times only; never changes deadlines, grades or receipts. */
(function(root){'use strict';
const skills={reading:'Reading',listening:'Listening',writing:'Writing',speaking:'Speaking',shadowing:'Shadowing'},minutes={reading:25,listening:25,writing:40,speaking:20,shadowing:15};
const rhythm=['Ôn bài và chuẩn bị buổi học','Reading & sổ từ vựng','Luyện Shadowing','Viết bài Writing','Ghi âm Speaking','Sửa bài Writing theo nhận xét','Hoàn thành bài còn thiếu'];
const DAY=86400000,escape=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=v=>Number.isFinite(v)?v.toLocaleString('vi-VN',{maximumFractionDigits:1}):'—';
const time=v=>root.IeltsStudyPlannerModel.timestamp(v,false);
const date=v=>{const at=typeof v==='number'?v:time(v);return at===null?'Chưa có hạn':new Date(at).toLocaleDateString('vi-VN',{timeZone:'Asia/Bangkok',day:'2-digit',month:'2-digit'});};
const stamp=v=>{const at=time(v);return at===null?'':new Date(at).toLocaleString('vi-VN',{timeZone:'Asia/Bangkok',day:'2-digit',month:'2-digit',hour:'2-digit',minute:'2-digit'});};
function link(task){const found=(task.links||[]).find(x=>{try{return /^https?:$/.test(new URL(x.url).protocol);}catch(_){return false;}});return found?'<a class="study-action" href="'+escape(found.url)+'" target="_blank" rel="noopener">Làm bài ngay ↗</a>':'<button class="study-action subtle" data-study-open="'+escape(skills[task.skill]?task.skill:'homework-all')+'">Xem hướng dẫn →</button>';}
function badge(t){const done=t.status==='done',urgency=t.status==='overdue'?'⛔ Quá hạn':t.status==='dueSoon'?'⚠️ Sắp đến hạn':'⏳ Cần làm';return '<span class="study-pill '+escape(t.status)+'">'+escape(done?t.statusLabel||'✅ ĐÃ NỘP':'— Chưa nộp bài')+'</span>'+(done?(t.submittedAt?'<small class="study-confirmed-time">'+escape(stamp(t.submittedAt))+'</small>':''):'<small class="study-urgency '+escape(t.status)+'">'+urgency+'</small>');}
function card(t,prefix){try{return '<article data-assignment-id="'+prefix+escape(t.id)+'" class="study-task '+escape(t.status)+'"><div class="study-task-top"><span class="study-skill">'+escape(skills[t.skill]||'Bài tập')+'</span><div class="study-state">'+badge(t)+'</div></div><h4>'+escape(t.title)+'</h4><p>Hạn nộp: '+escape(date(t.dueAt))+'</p><div class="study-task-bottom"><small>⏱️ ~'+(minutes[t.skill]||25)+' phút</small>'+link(t)+'</div></article>';}catch(_){return errorCard(t);}}
function errorCard(t){return '<article data-assignment-id="error-'+escape(t.id)+'" class="study-task study-card-error"><h4>'+escape(t.title||'Bài tập')+'</h4><p>Liên kết bài này chưa mở được. Em xem lại hướng dẫn hoặc báo cô để kiểm tra nhé.</p><button class="study-action subtle" data-study-open="'+escape(skills[t.skill]?t.skill:'homework-all')+'">Xem hướng dẫn</button></article>';}
function assignDays(model,startKey){const start=time(startKey),end=start+7*DAY,preferred={reading:1,listening:1,shadowing:2,writing:3,speaking:4},slots=Array.from({length:7},()=>[]);
 for(const t of model.tasks){let day=null;if(t.dueAt!==null&&t.dueAt>=start&&t.dueAt<end&&(t.status==='done'||t.dueAt>=model.now)){const dueIndex=Math.floor((time(t.dueDateKey)-start)/DAY),candidate=Math.min(preferred[t.skill]??dueIndex,dueIndex),released=time(t.source.assignedAt||t.source.releaseDate||t.source.lessonDate),releaseIndex=released===null?0:Math.max(0,Math.floor((released-start)/DAY));day=Math.min(dueIndex,Math.max(candidate,releaseIndex,t.status!=='done'&&startKey===root.IeltsStudyPlannerModel.mondayKey(model.now)?Math.floor((time(model.todayKey)-start)/DAY):0));}
 if(day!==null)slots[day].push(t);
 }return slots;}
function plan(model){const slots=assignDays(model,model.weekStart),todayStart=root.IeltsStudyPlannerModel.mondayKey(model.now),todaySlots=assignDays(model,todayStart),index=Math.floor((time(model.todayKey)-time(todayStart))/DAY),map=new Map();
 for(const t of [...model.todayTasks,...todaySlots[index],...model.priorities.filter(t=>t.status==='overdue').slice(0,2)])map.set(t.id,t);
 const todayTasks=[...map.values()],done=todayTasks.filter(t=>t.status==='done').length;
 return {slots,todayTasks,done,total:todayTasks.length,todayLessons:model.lessons.filter(l=>l.dateKey===model.todayKey)};}
function lesson(l){return '<article class="study-lesson" data-assignment-id="lesson-'+escape(l.id)+'"><span>HỌC TRÊN LỚP</span><strong>'+escape(l.title+' · '+l.session)+'</strong><small>'+escape([l.startTime,l.endTime].filter(Boolean).join(' – '))+'</small></article>';}
function planner(model){const p=plan(model),weekTasks=p.slots.flat(),weekDone=weekTasks.filter(t=>t.status==='done').length,progress=p.total?Math.round(100*p.done/p.total):0;return '<div class="study-hub study-v2"><header class="study-heading"><div><p class="study-eyebrow">IELTS 48 · KẾ HOẠCH CÁ NHÂN</p><h2>Thời gian biểu</h2><p>Việc cần làm hôm nay, nhịp tự luyện cả tuần.</p></div><button class="study-action subtle" data-study-open="schedule">📅 Xem lịch học cả khóa</button></header>'+
 '<section class="study-focus" data-history-section="today-action"><div class="study-section-title"><div><p class="study-eyebrow">1 · TIÊU ĐIỂM HÔM NAY · '+escape(date(model.now))+'</p><h3>Hôm nay cần làm gì?</h3></div><span class="study-focus-note">Ưu tiên hạn hôm nay và bài đã quá hạn</span></div><div class="study-day-progress"><strong>'+(p.total?'Hoàn thành '+p.done+'/'+p.total+' việc':'Hôm nay chưa có bài được lên lịch')+'</strong><progress max="100" value="'+progress+'" aria-label="Tiến độ bài tập hôm nay"></progress></div>'+
 p.todayLessons.map(lesson).join('')+(p.total?'<div class="study-priority-grid">'+p.todayTasks.map(t=>card(t,'today-')).join(''):'<p class="study-calm">Em có thể ôn lại bài và sửa lỗi theo nhận xét của cô. Xem kế hoạch bên dưới để chuẩn bị cho ngày tiếp theo nhé.</p>')+'</section>'+
 '<section class="study-week"><div class="study-section-title"><div><p class="study-eyebrow">2 · LỘ TRÌNH 7 NGÀY</p><h3>'+escape(date(model.weekStart))+' – '+escape(date(model.weekEnd))+'</h3><p>'+weekDone+'/'+weekTasks.length+' việc đã hoàn thành. Ngày tự luyện là gợi ý; hạn nộp và lịch học giữ theo dữ liệu của cô.</p></div><div class="study-week-controls"><button data-study-week="-1" aria-label="Tuần trước">←</button><button data-study-week="0">Tuần này</button><button data-study-week="1" aria-label="Tuần sau">→</button></div></div><div class="study-week-grid">'+model.days.map((d,i)=>'<section class="study-day '+(d.isToday?'today':'')+'"><div class="study-day-head"><strong>'+escape(d.label)+'</strong><span>'+escape(date(d.dateKey))+'</span>'+(d.isToday?'<b>Hôm nay</b>':'')+'</div><p class="study-rhythm">'+escape(rhythm[i])+'</p><div class="study-day-body">'+d.lessons.map(lesson).join('')+p.slots[i].slice(0,3).map(t=>card(t,'week-')).join('')+(p.slots[i].length>3?'<details data-history-section="week-more-'+i+'"><summary>Xem thêm '+(p.slots[i].length-3)+' việc</summary>'+p.slots[i].slice(3).map(t=>card(t,'week-')).join('')+'</details>':'')+(!p.slots[i].length?'<p class="study-day-empty">Chưa có bài cần nộp được xếp cho ngày này.</p><button class="study-action subtle" data-study-open="'+(['schedule','reading','shadowing','writing','speaking','writing','homework-all'][i])+'">Xem '+(i===0?'lịch học':'bài tập')+' →</button>':'')+'</div></section>').join('')+'</div></section>'+
 (model.weekOffset===0&&model.tasks.some(t=>t.status==='overdue')?'<section class="study-backlog"><details data-history-section="planner-backlog"><summary>Quá hạn cần hoàn thành · '+model.tasks.filter(t=>t.status==='overdue').length+' bài</summary><div class="study-priority-grid">'+model.tasks.filter(t=>t.status==='overdue').map(t=>card(t,'backlog-')).join('')+'</div></details></section>':'')+((model.errors||[]).length?'<section class="study-priority-grid">'+model.errors.map(errorCard).join('')+'</section>':'')+'<p class="study-footnote">Thời lượng là ước lượng để sắp xếp việc học. Trạng thái bài tập dùng chung với mục Bài tập 4 kỹ năng.</p></div>';}
function course(model){const total=model.tasks.length,done=model.tasks.filter(t=>t.status==='done').length;return {done,total,percent:total?Math.round(done/total*100):null};}
function overview(state,entry,model){const c=course(model);return '<section id="ielts48-personal-insights" class="study-personal-insights"><header><p class="study-eyebrow">KẾT QUẢ CỦA EM</p><h2>Điểm mạnh & hướng cải thiện</h2><p>Điểm kiểm tra theo bảng lớp; nhận xét và bảng điểm chi tiết ở ngay bên dưới.</p></header><div class="study-band-chart" role="img" aria-label="Biểu đồ điểm bốn kỹ năng trên thang 9">'+['listening','speaking','reading','writing'].map(k=>{const component=entry?.components?.[k],band=Number.isFinite(component?.band)?component.band:null;return '<div class="study-band-row"><strong>'+skills[k]+'</strong><div class="study-track"><i style="width:'+(band===null?0:Math.max(0,Math.min(100,band/9*100)))+'%"></i></div><b>'+fmt(band)+(band===null?'':' / 9')+'</b><small>'+escape(component?.sourceDate||'Chưa có điểm')+'</small></div>';}).join('')+'</div><div class="study-course-progress"><strong>Tiến độ bài tập khóa học <b>'+c.done+'/'+c.total+' bài'+'</b></strong><progress max="100" value="'+(c.percent||0)+'" aria-label="Tiến độ bài tập khóa học"></progress><p>'+c.done+'/'+c.total+' bài đã hoàn thành trong dữ liệu được giao hiện có. Không dùng tỷ lệ này để kết luận đã hoàn thành toàn bộ chương trình.</p></div></section>';}
function component(entry,key){if(key==='habit'){const c=entry?.coverage?.habit;return c?c.completedShadowing+'/'+c.shadowingEligible+' bài Shadowing · '+c.onTime+'/'+c.known+' bài đúng hạn':'Chưa đủ dữ liệu';}const band=entry?.components?.[key]?.band;return Number.isFinite(band)?'Band '+fmt(band):'Chưa có điểm';}
function explanation(entry,model){const c=entry?.coverage?.habit,p=course(model);return '<details class="study-method study-score-explanation" data-history-section="study-personal-detail" id="study-personal-detail"><summary>Vì sao em có điểm tích lũy này?</summary><p>Điểm tích lũy giữ nguyên tỷ trọng 20% cho mỗi kỹ năng và 20% cho Chuyên cần & Đúng hạn.</p><ul>'+['reading','listening','writing','speaking'].map(k=>{const v=entry?.components?.[k]?.value;return '<li>'+skills[k]+': '+escape(component(entry,k))+' · đóng góp '+fmt(Number.isFinite(v)?v*.2:null)+'/20 điểm.</li>';}).join('')+'</ul>'+(c?'<p>Trong phạm vi tính hạng 8 tuần: hoàn thành '+c.completedShadowing+'/'+c.shadowingEligible+' bài Shadowing; còn '+(c.shadowingEligible-c.completedShadowing)+' bài chưa hoàn thành. Có '+c.onTime+'/'+c.known+' bài đúng hạn; '+(c.known-c.onTime)+' bài chưa được ghi nhận đúng hạn (không đồng nghĩa tất cả đều chưa nộp).</p>':'<p>Chưa đủ dữ liệu về chuyên cần.</p>')+'<p>Trong toàn bộ bài tập hiện được giao cho em: '+p.done+'/'+p.total+' bài đã hoàn thành, '+(p.total-p.done)+' bài còn cần xử lý. Phạm vi này khác phạm vi tính hạng 8 tuần.</p></details>';}
const bound=new WeakSet();function bind(host){const detail=host.querySelector('#study-personal-detail');host.querySelectorAll('[data-study-mine]').forEach(row=>{const expanded=String(!!detail?.open);if(row.getAttribute('aria-expanded')!==expanded)row.setAttribute('aria-expanded',expanded);});if(bound.has(host))return;bound.add(host);function toggle(e){const row=e.target.closest('[data-study-mine]');if(!row)return;const d=host.querySelector('#study-personal-detail');if(d){d.open=!d.open;row.setAttribute('aria-expanded',String(d.open));if(d.open)d.scrollIntoView({block:'nearest',behavior:'smooth'});}}host.addEventListener('click',toggle);host.addEventListener('keydown',e=>{if(e.target.closest('[data-study-mine]')&&['Enter',' '].includes(e.key)){e.preventDefault();toggle(e);}});}
root.Ielts48Experience={plan,planner,overview,component,explanation,bind,course};
})(globalThis);
